const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Lake Kariba approximate bounding box
  const geometry = ee.Geometry.Polygon(
    [[[26.9, -18.2],
      [26.9, -16.3],
      [29.7, -16.3],
      [29.7, -18.2]]]);

  const year1 = 2018;
  const year2 = 2019;
  const month = 12; // December

  const startDate1 = ee.Date.fromYMD(year1, month, 1);
  const endDate1 = ee.Date.fromYMD(year1, month, 31);
  const startDate2 = ee.Date.fromYMD(year2, month, 1);
  const endDate2 = ee.Date.fromYMD(year2, month, 31);

  const scale = 1000; // Resolution for reduction in meters, to avoid timeout

  // Function to mask clouds from S2_SR data.
  // Uses the SCL (Scene Classification Layer) band.
  function maskS2clouds(image) {
    var scl = image.select('SCL');
    // Clouds, cirrus, cloud shadows, snow/ice
    var maskedSCL = scl.neq(3).and(scl.neq(8)).and(scl.neq(9)).and(scl.neq(10)).and(scl.neq(11));
    return image.updateMask(maskedSCL);
  }

  // Function to calculate MNDWI for Sentinel-2
  function calculateMNDWI(image) {
    // MNDWI = (Green - SWIR1) / (Green + SWIR1)
    // S2 bands: B3 (Green), B11 (SWIR1)
    return image.normalizedDifference(['B3', 'B11']).rename('MNDWI');
  }

  // Function to process image collection for a given period
  async function processCollection(startDate, endDate, year) {
    let collection = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)) // Filter out very cloudy images
      .map(maskS2clouds); // Apply cloud mask

    const collectionSize = await collection.size().getInfo();
    if (collectionSize === 0) {
      return { area: null, count: 0, size: 0, cloud_percent: 0 };
    }

    // Calculate median composite
    const composite = collection.median();

    // Calculate MNDWI
    const mndwi = calculateMNDWI(composite);

    // Threshold MNDWI to get water mask (MNDWI > 0.2 is a common threshold)
    const waterMask = mndwi.gt(0.2).rename('water_mask');

    // Calculate pixel area
    const pixelArea = ee.Image.pixelArea().rename('pixel_area');

    // Multiply water mask by pixel area to get water area in square meters
    const waterAreaImage = waterMask.multiply(pixelArea).updateMask(waterMask);

    // Reduce region to sum water area and count valid pixels
    const stats = await waterAreaImage.reduceRegion({
      reducer: ee.Reducer.sum().unweighted().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();

    const water_sq_m = stats ? stats.water_mask_sum : null;
    const valid_pixels = stats ? stats.water_mask_count : 0;

    // Calculate average cloud percentage for debugging
    const avgCloudyPercentage = collection.aggregate_mean('CLOUDY_PIXEL_PERCENTAGE');
    const cloud_percent = await avgCloudyPercentage.getInfo();

    return {
      area: water_sq_m,
      count: valid_pixels,
      size: collectionSize,
      cloud_percent: cloud_percent
    };
  }

  // 2. Data Acquisition & Check for 2018
  const stats18 = await processCollection(startDate1, endDate1, year1);
  console.log(`2018 Images: ${stats18.size} (Avg Cloud: ${stats18.cloud_percent !== null ? stats18.cloud_percent.toFixed(2) : 'N/A'}%)`);
  if (stats18.size === 0) {
    console.log("No images found for December 2018.");
    console.log("C1");
    return;
  }
  if (stats18.count === 0) {
    console.log("No valid pixels for Lake Kariba in December 2018 after masking.");
    console.log("C2");
    return;
  }

  // 3. Data Acquisition & Check for 2019
  const stats19 = await processCollection(startDate2, endDate2, year2);
  console.log(`2019 Images: ${stats19.size} (Avg Cloud: ${stats19.cloud_percent !== null ? stats19.cloud_percent.toFixed(2) : 'N/A'}%)`);
  if (stats19.size === 0) {
    console.log("No images found for December 2019.");
    console.log("C1");
    return;
  }
  if (stats19.count === 0) {
    console.log("No valid pixels for Lake Kariba in December 2019 after masking.");
    console.log("C2");
    return;
  }

  // 4. Calculation & Validation
  const waterArea18_km2 = stats18.area ? stats18.area / 1e6 : null;
  const waterArea19_km2 = stats19.area ? stats19.area / 1e6 : null;

  if (waterArea18_km2 === null || waterArea19_km2 === null) {
    console.log("Calculation failed: Water area is null.");
    console.log("C3");
    return;
  }

  console.log(`2018 Water Area: ${waterArea18_km2.toFixed(2)} km^2 (Pixels: ${stats18.count})`);
  console.log(`2019 Water Area: ${waterArea19_km2.toFixed(2)} km^2 (Pixels: ${stats19.count})`);

  if (waterArea19_km2 > waterArea18_km2) {
    console.log("A"); // Yes, water levels in 2019 were higher
  } else {
    console.log("B"); // No, water levels in 2019 were not higher
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
